function score(p){
  p=String(p||'').trim(); var s=0; var sug=[];
  if(p.length<20) sug.push('提示词偏短，建议补充背景与目标');
  else if(p.length<=300) s+=30;
  else { s+=20; sug.push('过长，可拆分为多个子任务'); }
  if(/角色|role|你是一个|你是|assume/i.test(p)) s+=25; else sug.push('缺少明确的角色设定');
  if(/任务|请|生成|写|总结|解释|分析/i.test(p)) s+=25; else sug.push('未说明具体任务');
  if(/格式|输出|json|表格|要点|markdown|分步骤/i.test(p)) s+=20; else sug.push('未指定输出格式');
  return {score:s, suggestions:sug};
}
var EXPORTS={score:score};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PromptScoreForgePure = EXPORTS; }
